"use client";

import {
  AUTH_COOKIE_NAME,
  clearSessionCookieString,
  parseSessionCookie,
  serializeSessionCookie,
} from "@/app/lib/auth";
import { createDefaultFlow } from "@/app/lib/workflow";
import type {
  AuthSession,
  LoginPayload,
  MockUser,
  SaveFlowPayload,
  SignupPayload,
  WorkflowDocument,
} from "@/app/lib/types";

const USERS_STORAGE_KEY = "forgeflow_users";
const SESSION_STORAGE_KEY = "forgeflow_auth";
const FLOW_STORAGE_PREFIX = "forgeflow_flow_";

const seededUsers: MockUser[] = [
  {
    id: "user-demo",
    name: "Blueprint Demo",
    email: "demo@forgeflow.local",
    password: "Demo123!",
    createdAt: "2026-03-23T00:00:00.000Z",
  },
];

function wait(ms = 250) {
  return new Promise((resolve) => {
    window.setTimeout(resolve, ms);
  });
}

function readJSON<T>(key: string, fallback: T) {
  if (typeof window === "undefined") {
    return fallback;
  }

  const raw = window.localStorage.getItem(key);

  if (!raw) {
    return fallback;
  }

  try {
    return JSON.parse(raw) as T;
  } catch {
    return fallback;
  }
}

function writeJSON<T>(key: string, value: T) {
  window.localStorage.setItem(key, JSON.stringify(value));
}

function getFlowStorageKey(userId: string) {
  return `${FLOW_STORAGE_PREFIX}${userId}`;
}

function normalizeSession(session: AuthSession) {
  writeJSON(SESSION_STORAGE_KEY, session);
  document.cookie = serializeSessionCookie(session);
  return session;
}

function clearStoredSession() {
  window.localStorage.removeItem(SESSION_STORAGE_KEY);
  document.cookie = clearSessionCookieString();
}

function readUsers() {
  const users = readJSON<MockUser[]>(USERS_STORAGE_KEY, seededUsers);

  if (users.length === 0) {
    writeJSON(USERS_STORAGE_KEY, seededUsers);
    return seededUsers;
  }

  if (users === seededUsers) {
    writeJSON(USERS_STORAGE_KEY, seededUsers);
  }

  return users;
}

function writeUsers(users: MockUser[]) {
  writeJSON(USERS_STORAGE_KEY, users);
}

function getCookieValue(name: string) {
  const raw = document.cookie
    .split("; ")
    .find((part) => part.startsWith(`${name}=`));

  return raw ? raw.slice(name.length + 1) : null;
}

function toSession(user: MockUser): AuthSession {
  return {
    token: `token-${user.id}`,
    user: {
      id: user.id,
      name: user.name,
      email: user.email,
    },
  };
}

export async function getSession() {
  if (typeof window === "undefined") {
    return null;
  }

  await wait(100);

  const storedSession = readJSON<AuthSession | null>(SESSION_STORAGE_KEY, null);

  if (storedSession) {
    return storedSession;
  }

  const cookieSession = parseSessionCookie(getCookieValue(AUTH_COOKIE_NAME));

  if (cookieSession) {
    writeJSON(SESSION_STORAGE_KEY, cookieSession);
  }

  return cookieSession;
}

export async function signup(payload: SignupPayload) {
  await wait();

  const users = readUsers();
  const email = payload.email.trim().toLowerCase();

  if (payload.name.trim().length < 2) {
    throw new Error("Name should be at least 2 characters.");
  }

  if (payload.password.trim().length < 6) {
    throw new Error("Password should be at least 6 characters.");
  }

  if (users.some((user) => user.email.toLowerCase() === email)) {
    throw new Error("An account with that email already exists.");
  }

  const user: MockUser = {
    id: `user-${Math.random().toString(36).slice(2, 10)}`,
    name: payload.name.trim(),
    email,
    password: payload.password,
    createdAt: new Date().toISOString(),
  };

  writeUsers([...users, user]);

  const starterFlow = createDefaultFlow(`${user.name.split(" ")[0]}'s Workflow`);
  writeJSON(getFlowStorageKey(user.id), starterFlow);

  return normalizeSession(toSession(user));
}

export async function login(payload: LoginPayload) {
  await wait();

  const email = payload.email.trim().toLowerCase();
  const user = readUsers().find(
    (entry) =>
      entry.email.toLowerCase() === email && entry.password === payload.password,
  );

  if (!user) {
    throw new Error("Invalid email or password.");
  }

  return normalizeSession(toSession(user));
}

export async function logout() {
  if (typeof window === "undefined") {
    return;
  }

  await wait(100);
  clearStoredSession();
}

export async function loadFlow(userId: string) {
  await wait(180);

  const existing = readJSON<WorkflowDocument | null>(
    getFlowStorageKey(userId),
    null,
  );

  if (existing) {
    return existing;
  }

  const user = readUsers().find((entry) => entry.id === userId);
  const seeded = createDefaultFlow(
    user ? `${user.name.split(" ")[0]}'s Workflow` : "Blueprint Workspace",
  );

  writeJSON(getFlowStorageKey(userId), seeded);
  return seeded;
}

export async function saveFlow({
  userId,
  document,
  mode,
}: SaveFlowPayload) {
  await wait(mode === "manual" ? 240 : 120);

  const nextDocument: WorkflowDocument = {
    ...document,
    updatedAt: new Date().toISOString(),
    saveMode: mode,
  };

  writeJSON(getFlowStorageKey(userId), nextDocument);
  return nextDocument;
}
