import type { AuthSession } from "@/app/lib/types";

export const AUTH_COOKIE_NAME = "forgeflow_session";
export const AUTH_COOKIE_MAX_AGE = 60 * 60 * 24 * 7;

export function serializeSessionCookie(session: AuthSession) {
  return [
    `${AUTH_COOKIE_NAME}=${encodeURIComponent(JSON.stringify(session))}`,
    `Max-Age=${AUTH_COOKIE_MAX_AGE}`,
    "Path=/",
    "SameSite=Lax",
  ].join("; ");
}

export function clearSessionCookieString() {
  return [
    `${AUTH_COOKIE_NAME}=`,
    "Max-Age=0",
    "Path=/",
    "SameSite=Lax",
  ].join("; ");
}

export function parseSessionCookie(cookieValue?: string | null) {
  if (!cookieValue) {
    return null;
  }

  try {
    return JSON.parse(decodeURIComponent(cookieValue)) as AuthSession;
  } catch {
    return null;
  }
}
